describe('File Upload Error Handling', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should display an error message for disallowed file type', () => {
        const fileName = 'test.txt'; // Replace with a disallowed file type
        cy.get('input[type="file"]').attachFile(fileName);
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('be.visible').and('contain', 'File type not allowed');
    });

    it('should not display an error message for allowed file type', () => {
        const fileName = 'test.pdf'; // Replace with an allowed file type
        cy.get('input[type="file"]').attachFile(fileName);
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('not.exist');
    });
});
